-- 030: Base de comparação nas pesquisas e modelo embutido "Cultura organizacional".
-- 1) surveys.baseline: resultado de uma aplicação anterior, só em percentuais por pergunta (nenhuma resposta
--    individual), para mostrar "antes x agora" nos resultados. Fica com a pesquisa da empresa, não no modelo.
-- 2) Modelo "Cultura organizacional": 46 afirmações em escala de concordância de 5 pontos, agrupadas em
--    5 dimensões (credibilidade, respeito, imparcialidade, orgulho e camaradagem) e temas, e 7 indicadores com
--    escalas próprias (incluindo felicidade de 0 a 10). Padrão aplicado no Bismarchi | Pires (ORQESTRAI).

alter table public.surveys add column if not exists baseline jsonb;
alter table public.surveys drop constraint if exists surveys_baseline_object;
alter table public.surveys
  add constraint surveys_baseline_object check (baseline is null or jsonb_typeof(baseline) = 'object');
comment on column public.surveys.baseline is 'Resultado de uma aplicação anterior (percentuais por pergunta, sem respostas individuais), para comparar.';

insert into public.survey_templates (key, name, description, intro, questions, builtin)
values (
  'cultura-organizacional',
  $nome$Cultura organizacional$nome$,
  $descricao$Pesquisa de clima e cultura com 46 afirmações em 5 dimensões (credibilidade, respeito, imparcialidade, orgulho e camaradagem) e 7 indicadores, incluindo felicidade de 0 a 10.$descricao$,
  $intro$Esta pesquisa ajuda a entender como as pessoas percebem a cultura e o clima da empresa: liderança, respeito, justiça, orgulho do trabalho e relação entre colegas. É anônima: não pedimos nome, e-mail, cargo nem setor, e as respostas são analisadas apenas em conjunto. Responda com sinceridade: não há respostas certas ou erradas.$intro$,
  $perguntas$[{"id":"p1","type":"escala","text":"Os gestores me mantêm informados sobre mudanças na empresa.","required":true,"section":"Credibilidade","theme":"Comunicação da liderança","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"p2","type":"escala","text":"Os gestores deixam claras suas expectativas.","required":true,"section":"Credibilidade","theme":"Comunicação da liderança","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"p3","type":"escala","text":"É fácil se aproximar dos gestores e falar com eles.","required":true,"section":"Credibilidade","theme":"Comunicação da liderança","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"p5","type":"escala","text":"Posso fazer qualquer pergunta razoável e obter respostas diretas.","required":true,"section":"Credibilidade","theme":"Comunicação da liderança","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"p4","type":"escala","text":"Os gestores são competentes para tocar o negócio.","required":true,"section":"Credibilidade","theme":"Competência da liderança","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"p6","type":"escala","text":"Os gestores contratam pessoas que se enquadram bem aqui.","required":true,"section":"Credibilidade","theme":"Competência da liderança","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"p7","type":"escala","text":"Os gestores sabem coordenar e distribuir tarefas.","required":true,"section":"Credibilidade","theme":"Competência da liderança","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"p8","type":"escala","text":"Os gestores confiam que as pessoas fazem bom trabalho sem vigiá-las.","required":true,"section":"Credibilidade","theme":"Competência da liderança","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"p9","type":"escala","text":"Os gestores dão autonomia às pessoas.","required":true,"section":"Credibilidade","theme":"Competência da liderança","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"p10","type":"escala","text":"Os gestores têm visão clara de para onde estamos indo.","required":true,"section":"Credibilidade","theme":"Competência da liderança","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"p11","type":"escala","text":"Os gestores cumprem o que prometem.","required":true,"section":"Credibilidade","theme":"Integridade da liderança","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"p12","type":"escala","text":"Os gestores agem de acordo com o que falam.","required":true,"section":"Credibilidade","theme":"Integridade da liderança","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"p13","type":"escala","text":"Os gestores só promoveriam reduções de quadro como último recurso.","required":true,"section":"Credibilidade","theme":"Integridade da liderança","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"p14","type":"escala","text":"Os gestores são honestos e éticos na condução dos negócios.","required":true,"section":"Credibilidade","theme":"Integridade da liderança","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"p15","type":"escala","text":"A empresa oferece treinamento ou outras formas de desenvolvimento.","required":true,"section":"Respeito","theme":"Apoio e desenvolvimento","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"p16","type":"escala","text":"Recebo os equipamentos e recursos necessários para o meu trabalho.","required":true,"section":"Respeito","theme":"Apoio e desenvolvimento","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"r9","type":"escala","text":"Os gestores agradecem o bom trabalho e o esforço extra.","required":true,"section":"Respeito","theme":"Apoio e desenvolvimento","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"r10","type":"escala","text":"Meu superior me encoraja a contribuir com ideias.","required":true,"section":"Respeito","theme":"Apoio e desenvolvimento","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"s1","type":"escala","text":"Este é um lugar fisicamente seguro para trabalhar.","required":true,"section":"Respeito","theme":"Cuidado e bem-estar","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"s2","type":"escala","text":"Este é um lugar psicológica e emocionalmente saudável.","required":true,"section":"Respeito","theme":"Cuidado e bem-estar","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"s3","type":"escala","text":"Nossas instalações contribuem para um bom ambiente.","required":true,"section":"Respeito","theme":"Cuidado e bem-estar","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"s4","type":"escala","text":"Posso me ausentar do trabalho quando necessário.","required":true,"section":"Respeito","theme":"Cuidado e bem-estar","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"s5","type":"escala","text":"A liderança me incentiva a equilibrar vida pessoal e profissional.","required":true,"section":"Respeito","theme":"Cuidado e bem-estar","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"s6","type":"escala","text":"A liderança me trata com respeito como profissional e como pessoa.","required":true,"section":"Respeito","theme":"Cuidado e bem-estar","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"r3","type":"escala","text":"Sinto-me valorizado(a) pelo trabalho que realizo.","required":true,"section":"Respeito","theme":"Reconhecimento","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"r4","type":"escala","text":"Recebo reconhecimento adequado pelo meu desempenho no trabalho.","required":true,"section":"Respeito","theme":"Reconhecimento","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"r5","type":"escala","text":"Consigo equilibrar bem minhas responsabilidades profissionais e pessoais.","required":true,"section":"Respeito","theme":"Equilíbrio vida/trabalho","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"r6","type":"escala","text":"A empresa promove um bom equilíbrio entre trabalho e vida pessoal.","required":true,"section":"Respeito","theme":"Equilíbrio vida/trabalho","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"s7","type":"escala","text":"Meu salário é justo pelo trabalho que executo.","required":true,"section":"Imparcialidade","theme":"Remuneração e benefícios","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"q2","type":"escala","text":"A quantia que recebo como participação nos resultados é justa.","required":true,"section":"Imparcialidade","theme":"Remuneração e benefícios","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"q3","type":"escala","text":"Temos benefícios especiais e diferenciados aqui.","required":true,"section":"Imparcialidade","theme":"Remuneração e benefícios","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"q4","type":"escala","text":"Todos têm a oportunidade de receber um reconhecimento especial.","required":true,"section":"Imparcialidade","theme":"Remuneração e benefícios","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"q5","type":"escala","text":"Sou considerado(a) importante independentemente da minha posição.","required":true,"section":"Imparcialidade","theme":"Meritocracia","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"q6","type":"escala","text":"As promoções são dadas às pessoas que realmente mais merecem.","required":true,"section":"Imparcialidade","theme":"Meritocracia","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"q7","type":"escala","text":"Os gestores evitam o favoritismo.","required":true,"section":"Imparcialidade","theme":"Meritocracia","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"q8","type":"escala","text":"As pessoas evitam “politicagem” e intrigas.","required":true,"section":"Imparcialidade","theme":"Meritocracia","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"d1","type":"escala","text":"As pessoas são bem tratadas independentemente de cor ou etnia.","required":true,"section":"Imparcialidade","theme":"Diversidade e justiça","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"d2","type":"escala","text":"As pessoas são bem tratadas independentemente da idade.","required":true,"section":"Imparcialidade","theme":"Diversidade e justiça","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"d3","type":"escala","text":"As pessoas são bem tratadas independentemente do sexo.","required":true,"section":"Imparcialidade","theme":"Diversidade e justiça","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"d4","type":"escala","text":"As pessoas são bem tratadas independentemente da orientação sexual.","required":true,"section":"Imparcialidade","theme":"Diversidade e justiça","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"d5","type":"escala","text":"Se for tratado(a) injustamente, serei ouvido(a) e receberei tratamento justo.","required":true,"section":"Imparcialidade","theme":"Diversidade e justiça","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"d6","type":"escala","text":"A empresa tem um ambiente que respeita a diversidade e a inclusão.","required":true,"section":"Imparcialidade","theme":"Diversidade e justiça","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"r1","type":"escala","text":"Sinto que o meu trabalho tem um propósito significativo.","required":true,"section":"Orgulho","theme":"Propósito do trabalho","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"r2","type":"escala","text":"As atividades que realizo no meu trabalho são importantes para mim.","required":true,"section":"Orgulho","theme":"Propósito do trabalho","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"r7","type":"escala","text":"Tenho boas relações interpessoais no meu ambiente de trabalho.","required":true,"section":"Camaradagem","theme":"Relações entre colegas","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"r8","type":"escala","text":"O ambiente de trabalho é saudável e colaborativo.","required":true,"section":"Camaradagem","theme":"Relações entre colegas","allowNR":false,"labels":["Discordo totalmente","Discordo","Nem discordo, nem concordo","Concordo","Concordo totalmente"]},{"id":"ind_comunicacao","type":"escala","text":"Como você avalia a comunicação interna na empresa?","required":true,"section":"Indicadores","theme":"Comunicação interna","allowNR":false,"labels":["Muito ruim","Ruim","Média","Boa","Excelente"]},{"id":"ind_motivacao","type":"escala","text":"Você se sente motivado(a) no seu trabalho diário?","required":true,"section":"Indicadores","theme":"Motivação","allowNR":false,"labels":["Nunca","Raramente","Às vezes","Frequentemente","Sempre"]},{"id":"ind_feedback_lideranca","type":"escala","text":"A liderança está aberta a feedback e sugestões das pessoas?","required":true,"section":"Indicadores","theme":"Abertura a feedback","allowNR":false,"labels":["Nunca","Raramente","Às vezes","Frequentemente","Sempre"]},{"id":"ind_feedback_construtivo","type":"escala","text":"Você tem acesso a feedback construtivo sobre o seu desempenho?","required":true,"section":"Indicadores","theme":"Feedback construtivo","allowNR":false,"labels":["Nunca","Raramente","Às vezes","Frequentemente","Sempre"]},{"id":"ind_saude_mental","type":"escala","text":"A empresa oferece suporte adequado para a saúde mental e o bem-estar das pessoas?","required":true,"section":"Indicadores","theme":"Saúde mental","allowNR":false,"labels":["Nunca","Raramente","Às vezes","Frequentemente","Sempre"]},{"id":"ind_equilibrio","type":"escala","text":"Como você classificaria o equilíbrio entre trabalho e vida pessoal na empresa?","required":true,"section":"Indicadores","theme":"Equilíbrio vida/trabalho","allowNR":false,"labels":["Muito desequilibrado","Pouco desequilibrado","Equilibrado","Bem equilibrado","Excelentemente equilibrado"]},{"id":"ind_felicidade","type":"nota","text":"De 0 a 10, que nota você daria para a sua felicidade geral no trabalho?","required":true,"section":"Indicadores","theme":"Felicidade"}]$perguntas$::jsonb,
  true
)
on conflict (key) do nothing;
